import { useState } from "react";

export default function Inventory() {
  const [items, setItems] = useState([
    { id: 1, name: "Rice", stock: 25, unit: "kg" },
    { id: 2, name: "Oil", stock: 10, unit: "ltr" }
  ]);

  const [selected, setSelected] = useState(1);
  const [newStock, setNewStock] = useState("");

  function updateStock() {
    if (newStock === "") return;

    setItems(items.map(item =>
      item.id === selected
        ? { ...item, stock: Number(newStock) }
        : item
    ));

    setNewStock("");
  }

  return (
    <div className="admin-grid-two">
      {/* INVENTORY TABLE */}
      <div>
        <h3 className="section-title">Inventory Status</h3>
        <table>
          <thead>
            <tr>
              <th>Item</th>
              <th>Stock</th>
              <th>Unit</th>
            </tr>
          </thead>
          <tbody>
            {items.map(i => (
              <tr key={i.id}>
                <td>{i.name}</td>
                <td>{i.stock}</td>
                <td>{i.unit}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* UPDATE STOCK */}
      <div>
        <h3 className="section-title">Update Inventory</h3>

        <select onChange={e => setSelected(Number(e.target.value))}>
          {items.map(i => (
            <option key={i.id} value={i.id}>{i.name}</option>
          ))}
        </select>

        <input
          type="number"
          placeholder="New Stock"
          value={newStock}
          onChange={e => setNewStock(e.target.value)}
        />

        <button className="btn btn-primary btn-sm" onClick={updateStock}>
          Update Stock
        </button>
      </div>
    </div>
  );
}
